Actionscript.script:
function 量子爆弹()
{
    var 敌方目标 = _root.gameworld[_parent.攻击目标];
    if (!敌方目标)
    {
        return;
    }

    // ---- 根据目标朝向计算偏移 ----
    var 偏移量 = 200;
    // 方法1：用 _xscale 判断（负数表示朝左）
    if (敌方目标._xscale < 0) {
        偏移量 = -200;
    }
    // 如果你的目标有专门的"方向"属性（如 "左"/"右"），则改为：
    // if (敌方目标.方向 == "左") { 偏移量 = -50; }

    var 子弹属性 = _root.子弹属性初始化(this, "量子爆弹", _parent);
    子弹属性.shootX = 敌方目标._x + 偏移量;   // 这里替换
	子弹属性.shootY = 敌方目标.Z轴坐标;
	子弹属性.shootZ = 敌方目标.Z轴坐标;
	子弹属性.声音 = "";
	子弹属性.霰弹值 = 1;
	子弹属性.子弹散射度 = 0;
	子弹属性.发射效果 = "";
	子弹属性.子弹种类 = "量子爆弹";
	子弹属性.子弹威力 = _parent.空手攻击力 * 10;
	子弹属性.子弹速度 = 0;
	子弹属性.击中地图效果 = "火花";
	子弹属性.Z轴攻击范围 = 40;
	子弹属性.击倒率 = 25;
	子弹属性.击中后子弹的效果 = "";
	子弹属性.伤害类型 = "魔法";
	子弹属性.魔法伤害属性 = "冲";
	_root.子弹区域shoot传递(子弹属性);
}
function 支援飞弹()
{
    var 敌方目标 = _root.gameworld[_parent.攻击目标];
    if (!敌方目标)
    {
        return;
    }

    // ---- 根据目标朝向计算偏移 ----
    var 偏移量 = 150;
    // 方法1：用 _xscale 判断（负数表示朝左）
    if (敌方目标._xscale < 0) {
        偏移量 = -150;
    }
    // 如果你的目标有专门的"方向"属性（如 "左"/"右"），则改为：
    // if (敌方目标.方向 == "左") { 偏移量 = -50; }

    var 子弹属性 = _root.子弹属性初始化(this, "支援飞弹", _parent);
    子弹属性.shootX = 敌方目标._x + 偏移量;   // 这里替换
    子弹属性.shootY = 敌方目标.Z轴坐标;
    子弹属性.shootZ = 敌方目标.Z轴坐标;
    子弹属性.声音 = "";
    子弹属性.霰弹值 = 1;
    子弹属性.子弹散射度 = 0;
    子弹属性.发射效果 = "";
    子弹属性.子弹种类 = "支援飞弹";
    子弹属性.子弹威力 = _parent.空手攻击力 * 8;
    子弹属性.子弹速度 = 0;
    子弹属性.击中地图效果 = "火花";
    子弹属性.Z轴攻击范围 = 40;
    子弹属性.击倒率 = 25;
    子弹属性.击中后子弹的效果 = "";
    _root.子弹区域shoot传递(子弹属性);
}
function 攻击时移动(慢速度, 快速度)
{
	if (_parent.方向 == "右")
	{
		_parent.移动("右",慢速度);
	}
	else if (_parent.方向 == "左")
	{
		_parent.移动("左",慢速度);
	}
}
function 攻击时四向移动(上, 下, 左, 右)
{
	if (上 != 0)
	{
		_parent.移动("上",上);
	}
	else if (下 != 0)
	{
		_parent.移动("下",下);
	}
	if (左 != 0)
	{
		_parent.方向改变("左");
		_parent.移动("左",左);
	}
	else if (右 != 0)
	{
		_parent.方向改变("右");
		_parent.移动("右",右);
	}
}
gotoAndPlay(_parent.近战招式);

