onClipEvent(enterFrame){

   _parent.攻击时移动(-4,0);
}

onClipEvent(load){
	子弹属性 = _root.子弹属性初始化(this);
if (_parent._parent.等级 >= 50) {
	子弹属性.声音 = "反坦克炮.wav";
	子弹属性.霰弹值 = 1;
	子弹属性.发射效果 = "发射器枪火";
	子弹属性.子弹散射度 = 2;
	子弹属性.子弹种类 = "蓝旋反坦克炮弹";
	子弹属性.子弹威力 =  _parent._parent.空手攻击力 * 8;
	子弹属性.子弹速度 = 8;
	子弹属性.Z轴攻击范围 = 20.
	子弹属性.击倒率 = 20;
	子弹属性.伤害类型 = "破击";
	子弹属性.魔法伤害属性 = "装甲";
	} else {
	子弹属性.声音 = "反坦克炮.wav";
	子弹属性.霰弹值 = 1;
	子弹属性.发射效果 = "发射器枪火";
	子弹属性.子弹散射度 = 2;
	子弹属性.子弹种类 = "蓝旋反坦克炮弹";
	子弹属性.子弹威力 =  _parent._parent.空手攻击力 * 7;
	子弹属性.子弹速度 = 8;
	子弹属性.Z轴攻击范围 = 20.
	子弹属性.击倒率 = 20;

	}

	// 公共属性（两边都需要）
	子弹属性.区域定位area = this.area;

	_root.子弹区域shoot传递(子弹属性);
}

onClipEvent(load){
	子弹属性 = _root.子弹属性初始化(this);

	//以下部分只需要更改需要更改的属性,其余部分可注释掉
	子弹属性.声音 = "re_pistol_DEagle.wav";
	子弹属性.霰弹值 = 1;
	子弹属性.发射效果 = "枪火";
	子弹属性.子弹散射度 = 7;
	子弹属性.子弹种类 = "穿刺子弹";
// 等级判断
	if (_parent._parent.等级 >= 50) {
		子弹属性.子弹威力 = _parent._parent.空手攻击力 * 3;
	} else {
		子弹属性.子弹威力 = _parent._parent.空手攻击力 * 1.5;
	}
	子弹属性.子弹速度 = 30;
	子弹属性.Z轴攻击范围 = 30.
	子弹属性.击倒率 = 7;
	子弹属性.水平击退速度 = NaN;
	子弹属性.垂直击退速度 = NaN;
	//子弹属性.毒 = 30;

	//非常用
	/*
	子弹属性.发射效果 = "";
	子弹属性.击中地图效果 = "火花".
	子弹属性.击中后子弹的效果 = "".
	子弹属性.命中率 = NaN.
	子弹属性.固伤 = NaN;
	子弹属性.百分比伤害 = NaN;
	子弹属性.血量上限击溃 = NaN;
	子弹属性.防御粉碎 = NaN;
	子弹属性.区域定位area = this.area;
	*/
	/*
	//已初始化内容，通常不需要重复赋值，可注释掉
	子弹属性.发射者 = 子弹属性.发射者.
	子弹属性.shootX = 子弹属性.shootX;
	子弹属性.shootY = 子弹属性.shootY;
	子弹属性.shootZ = 子弹属性.shootZ;
	子弹属性.子弹敌我属性 = 子弹属性.子弹敌我属性;
	*/
	_root.子弹区域shoot传递(子弹属性);
}

