		子弹属性.声音 = "火流.wav";
		子弹属性.霰弹值 = 1;
		子弹属性.子弹散射度 = 0;
		子弹属性.子弹种类 = "近战子弹";
		子弹属性.子弹威力 = _parent._parent.空手攻击力* 1.1;
		子弹属性.子弹速度 = 0;
		子弹属性.Z轴攻击范围 = 30;
		子弹属性.击倒率 = 10;
		子弹属性.水平击退速度 = 10;
		子弹属性.垂直击退速度 = 3;
		子弹属性.伤害类型 = "魔法";
		子弹属性.魔法伤害属性 = "热";


	} else {
		// ========== 等级范围外 ==========
		子弹属性.声音 = "火流.wav";  
		子弹属性.霰弹值 = 1;
		子弹属性.子弹散射度 = 0;
		子弹属性.子弹种类 = "近战子弹";
		子弹属性.子弹威力 = _parent._parent.空手攻击力* 1.5;
		子弹属性.子弹速度 = 0;
		子弹属性.Z轴攻击范围 = 30;
		子弹属性.击倒率 = 10;
		子弹属性.水平击退速度 = 10;
		子弹属性.垂直击退速度 = 3;

	}

	// 公共属性（两边都需要）
	子弹属性.发射效果 = "高爆枪火";
	子弹属性.区域定位area = this.area;

	子弹属性.lightBinding = "area.heat";
	子弹属性.lightCastId = _parent.__projectileLightCast;
	子弹属性.lightSourceSlot = 1444;
	子弹属性.lightFacing = _parent._parent.方向 == "左" ? -1 : 1;
	_root.子弹区域shoot传递(子弹属性);
}

onClipEvent(load){
	子弹属性 = _root.子弹属性初始化(this);
	if (_parent._parent.等级 >= 50) {
	子弹属性.声音 = "shoot.wav";
	子弹属性.霰弹值 = 1;
	子弹属性.发射效果 = "发射器枪火";
	子弹属性.子弹散射度 = 3;
	子弹属性.子弹种类 = "普通火箭弹";
	子弹属性.子弹威力 =  _parent._parent.空手攻击力 * 4;
	子弹属性.子弹速度 = 6;
	子弹属性.Z轴攻击范围 = 20.
	子弹属性.击倒率 = 10;
	子弹属性.伤害类型 = "破击";
	子弹属性.魔法伤害属性 = "装甲";
	} else {
	子弹属性.声音 = "shoot.wav";
	子弹属性.霰弹值 = 1;
	子弹属性.发射效果 = "发射器枪火";
	子弹属性.子弹散射度 = 3;
	子弹属性.子弹种类 = "普通火箭弹";
	子弹属性.子弹威力 =  _parent._parent.空手攻击力 * 3;
	子弹属性.子弹速度 = 6;
	子弹属性.Z轴攻击范围 = 20.
	子弹属性.击倒率 = 10;

	}

	// 公共属性（两边都需要）
	子弹属性.区域定位area = this.area;

	_root.子弹区域shoot传递(子弹属性);
}
